import{_ as t,o as a,c as s,b6 as e,gE as l,gF as o,gG as r,gH as n,gI as h,gJ as p,gK as u,gL as d,gM as g,gN as c,gO as b,gP as k,gQ as m,gR as G,gS as H,gT as S,gU as q,gV as y,gW as F,gX as f,gY as _}from"./chunks/framework.BUXTSoD9.js";const A=JSON.parse('{"title":"سير عمل Git و GitHub","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/backend/git-workflow/index.md","filePath":"ar-sa/stage-2/backend/git-workflow/index.md"}'),C={name:"ar-sa/stage-2/backend/git-workflow/index.md"};function x(P,i,T,v,B,E){return a(),s("div",null,[...i[0]||(i[0]=[e('<h1 id="سير-عمل-git-و-github" tabindex="-1">سير عمل Git و GitHub <a class="header-anchor" href="#سير-عمل-git-و-github" aria-label="Permalink to “سير عمل Git و GitHub”">​</a></h1><p>في الدروس السابقة، تعلمنا كيفية استخدام أدوات vibe coding القائمة على الويب لكتابة الكود. كل محادثة تنشئ إصدارًا جديدًا من الكود. لكن دعونا نفكر في سؤال: إذا أردنا العودة إلى تعديل سابق، هل هناك طريقة سهلة؟ هل توجد أداة يمكنها تسجيل الكود في مراحله المختلفة، بحيث نتمكن من التبديل والتعديل بين الإصدارات المختلفة في أي وقت؟</p><p>لتلبية هذه الحاجة، ظهرت برامج التحكم في الإصدارات. في هذه المقالة، سنقدم أشهر برنامج للتحكم في الإصدارات — Git — وأفضل منصة لاستضافة الكود — GitHub. سنتعلم كيفية استخدام Git لإدارة الكود، وكيفية الحصول على كود الآخرين من GitHub، وكيفية رفع كودنا الخاص، وكيفية التعاون مع الآخرين في المشاريع الكبيرة.</p><p>سواء كان ذلك لتتبع إصدارات المشروع الشخصي، أو مزامنة الكود في العمل الجماعي، أو المساهمة في مجتمع المصادر المفتوحة، فإن Git و GitHub هما أدوات أساسية للمطورين المعاصرين. من خلال إتقانهما، ستتمكن من إدارة الكود بكفاءة أكبر، وإنشاء نقاط فحص حسب الحاجة، والتنقل بحرية بين مراحل الكود المختلفة، والتعامل بسهولة مع كل شيء بدءًا من تغيير ملف واحد إلى تطوير مشاريع كبيرة — مما يجعل كل تكرار للكود خاضعًا للتحكم وقابلًا للتتبع.</p><blockquote><p>💡 <strong>المعارف المسبقة</strong></p><p>قبل تعلم Git، يُنصح بأن تكون على دراية بالمفاهيم التالية:</p><ul><li><a href="/easy-vibe-ja-learning-map/ar-sa/appendix/2-development-tools/command-line-shell.html">ما هو الطرفية/سطر الأوامر</a> - تعلم كيفية استخدام سطر الأوامر للتفاعل مع الحاسوب</li><li><a href="/easy-vibe-ja-learning-map/ar-sa/appendix/2-development-tools/git-version-control.html">ما هو Git</a> - فهم المفاهيم الأساسية لنظام التحكم في إصدارات Git</li></ul><p>ستركز هذه المقالة على سير عمل GitHub والعمليات العملية، ويمكن الرجوع للمحتوى الأساسي عبر روابط <strong>الملحق</strong>.</p></blockquote><h1 id="البدء-السريع-مع-git" tabindex="-1">البدء السريع مع Git <a class="header-anchor" href="#البدء-السريع-مع-git" aria-label="Permalink to “البدء السريع مع Git”">​</a></h1><p>قبل البدء باستخدام Git، تأكد من أنك قرأت المحتوى في <strong>الملحق</strong> حول <a href="/easy-vibe-ja-learning-map/ar-sa/appendix/2-development-tools/command-line-shell.html">سطر الأوامر</a> و<a href="/easy-vibe-ja-learning-map/ar-sa/appendix/2-development-tools/git-version-control.html">أساسيات Git</a>. تفترض هذه المقالة أنك تملك هذه المعارف الأساسية، وتشرح مباشرة كيفية تثبيت وإعداد Git واستخدام GitHub للتعاون.</p><h2 id="كيفية-تثبيت-git" tabindex="-1">كيفية تثبيت Git <a class="header-anchor" href="#كيفية-تثبيت-git" aria-label="Permalink to “كيفية تثبيت Git”">​</a></h2><p>سنعرض ثلاث طرق لتثبيت Git على أنظمة تشغيل مختلفة. يرجى اتباع التعليمات حسب إصدار نظامك:</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h3><ol><li><p>انتقل إلى <a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">صفحة تحميل Git الرسمية</a> وقم بتنزيل برنامج التثبيت المناسب لنظامك: <a href="https://github.com/git-for-windows/git/releases/download/v2.51.0.windows.1/Git-2.51.0-64-bit.exe" target="_blank" rel="noreferrer">حزمة التثبيت</a>. بشكل افتراضي، يُنصح باستخدام مثبت x64.</p></li><li><p>انقر نقرًا مزدوجًا على برنامج التثبيت واتبع تعليمات معالج التثبيت: <img src="'+l+'" alt=""></p><ol><li>يُنصح بالحفاظ على الخيارات الافتراضية. إذا احتجت إلى التخصيص، يرجى <strong>ملاحظة</strong> النقاط التالية: (في معظم الحالات، يمكنك النقر باستمرار على &quot;Next&quot;) <ul><li>اختيار المحرر الافتراضي لـ Git: اختر المحرر المفضل لديك (مثل VS Code). يمكنك اختيار الخيار الأول افتراضيًا، وهو Vim (محرر نصوص)، أو اختيار خيار &quot;Visual Studio Code as Git&#39;s default editor&quot; (يتطلب تثبيت VS Code مسبقًا). يمكنك الاحتفاظ بالاختيار الافتراضي والنقر على &quot;Next&quot; للمتابعة. <img src="'+o+'" alt=""></li><li>اختيار كيفية استخدام Git: تتحكم هذه الخيارات الثلاثة في إمكانية الوصول إلى Git في النظام. يُنصح باختيار الخيار 2 (&quot;from command line and 3rd-party software&quot;) — فهو يضيف أدوات Git الأساسية إلى PATH، مما يتيح لك استخدام Git في Git Bash وموجه <strong>الأوامر</strong> و PowerShell وبيئات التطوير دون إحداث فوضى في النظام. <img src="'+r+'" alt=""></li></ul></li></ol></li><li><p>بعد التثبيت، انقر بزر الماوس الأيمن على سطح المكتب. إذا رأيت &quot;Git Bash Here&quot; في القائمة، فقد تم التثبيت بنجاح.</p></li></ol><p><img src="'+n+`" alt=""></p><h3 id="macos" tabindex="-1">MacOS <a class="header-anchor" href="#macos" aria-label="Permalink to “MacOS”">​</a></h3><p>بالنسبة لـ macOS، يمكنك أولاً إدخال <code>git --version</code> في الطرفية للتحقق مما إذا كان Git مثبتًا بالفعل. إذا لم يكن كذلك، سيُ<strong>نبه</strong>ك النظام للتثبيت — فقط اتبع التعليمات لإكمال التثبيت.</p><ol><li>الطريقة 1: التثبيت عبر Homebrew إذا قمت بتثبيت <a href="https://brew.sh/" target="_blank" rel="noreferrer">Homebrew</a> (مدير حزم Mac)، افتح الطرفية وأدخل<div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div></li><li>الطريقة 2: (مُوصى بها) التثبيت عبر Xcode: <a href="https://developer.apple.com/xcode/" target="_blank" rel="noreferrer">https://developer.apple.com/xcode/</a> ، يتضمن Xcode Git مدمجًا. بعد التثبيت، فقط اتبع التعليمات للمتابعة.</li></ol><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to “Linux”">​</a></h3><p>يمكن تثبيت Git على معظم توزيعات Linux عبر مدير الحزم:</p><ul><li>Ubuntu/Debian:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>CentOS/RHEL:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span></span></code></pre></div><ul><li>التحقق من التثبيت: أدخل <code>git --version</code> في الطرفية. إذا ظهر رقم الإصدار، فقد تم التثبيت بنجاح.</li></ul><h2 id="تهيئة-git" tabindex="-1">تهيئة Git <a class="header-anchor" href="#تهيئة-git" aria-label="Permalink to “تهيئة Git”">​</a></h2><p>بعد تثبيت Git، تحتاج أولاً إلى إعداد <strong>معلومات</strong> المستخدم — هذه <strong>خطوة</strong> أساسية لاستخدام Git في التحكم في الإصدارات. نفذ الأوامر التالية في الطرفية (استبدل المحتوى بين الأقواس بمعلوماتك الخاصة):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># تعيين اسم المستخدم العام (سيظهر في سجل الالتزامات)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Your Name&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># تعيين البريد الإلكتروني العام (يُنصح باستخدام البريد المسجل على GitHub/GitLab)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user.email</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your.email@example.com&quot;</span></span></code></pre></div><p>سيقوم Git بتضمين هذه <strong>المعلومات</strong> في كل سجل التزام، كـ&quot;معلومات المؤلف&quot; لكل تعديل. عند عرض سجل الإصدارات (مثلاً باستخدام <code>git log</code>)، يمكنك رؤية بوضوح من قام بتعديل كل سطر كود، مما يسهل تتبع المسؤولية والتواصل. في المشاريع التعاونية، تجعل <strong>معلومات</strong> الهوية الموحدة أعضاء الفريق قادرين على التعرف بسرعة على من أجرى التغييرات، مما يرفع كفاءة التعاون (مثلاً العثور على المطور المعني عبر سجلات الالتزام لمناقشة المشكلات).</p><p>يمكنك التحقق من <strong>معلومات</strong> إعدادات Git الحالية بإدخال <code>git config --list</code> في سطر الأوامر للتأكد من نجاح الإعداد.</p><h1 id="ما-هو-github" tabindex="-1">ما هو GitHub <a class="header-anchor" href="#ما-هو-github" aria-label="Permalink to “ما هو GitHub”">​</a></h1><p>GitHub هي منصة استضافة كود مبنية على Git. لا توفر فقط تخزينًا بعيدًا لمستودعات Git، بل تتضمن أيضًا أدوات تعاون (مثل Issues، Pull Requests، Projects)، مما يسهل على المطورين مشاركة الكود والتعاون. باختصار، Git هو أداة تحكم في الإصدارات محلية، بينما GitHub هو &quot;قرص سحابي لمستودعات الكود + مجتمع تعاوني&quot; بعيد.</p><p>GitHub ليست فقط أكبر منصة استضافة كود في العالم، بل هي أيضًا أكثر مجتمعات المصادر المفتوحة نشاطًا وتأثيرًا عالميًا. الفكرة الأساسية لـ &quot;المصادر المفتوحة&quot; هنا هي أن أي شخص يمكنه تنزيل وتشغيل الكود المصدري للبرنامج. يسمح هذا النموذج للأشخاص حول العالم بمراجعة كود بعضهم البعض وإجراء التعديلات، أو إنشاء مشاريع جديدة بناءً عليه. على سبيل المثال، يمكنك العثور على GitHub على دروس تعليمية متنوعة والكود المصدري الكامل لأطر تدريب نماذج GPT (مثل PyTorch). يوميًا، يتعاون عدد لا يحصى من الأشخاص حول العالم في مراجعة وتحسين الكود.</p><p><img src="`+h+'" alt=""></p><p>العديد من الشركات الكبرى تفتح مصدر برامجها أو دروسها على GitHub للحصول على ميزة تنافسية في الصناعة — ويمكن اعتبار ذلك شكلاً من أشكال الإعلان. في مجتمع GitHub، عدد &quot;النجوم (stars)&quot; التي يحصل عليها المشروع هو المؤشر الرئيسي لقياس قيمته؛ كلما زاد عدد النجوم التي يملكها المشروع أو المنظمة، زادت مصداقيته وتأثيره.</p><p><img src="'+p+'" alt=""></p><p>في دورتنا، سيتم رفع الموارد الداعمة والواجبات أيضًا إلى مستودع GitHub مخصص. من خلال عملية رفع الواجبات، ستتعلم تدريجيًا وتتقن استخدام GitHub، مما يضع أساسًا متينًا للتحكم في الإصدارات في تطوير التطبيقات المستقبلي.</p><h2 id="إنشاء-حساب-github" tabindex="-1">إنشاء حساب GitHub <a class="header-anchor" href="#إنشاء-حساب-github" aria-label="Permalink to “إنشاء حساب GitHub”">​</a></h2><ol><li>انتقل إلى <a href="https://github.com/" target="_blank" rel="noreferrer">موقع GitHub الرسمي</a> وانقر على &quot;Sign up&quot; في الزاوية العلوية اليمنى. <img src="'+u+'" alt=""></li><li>أدخل عنوان بريدك الإلكتروني (يُنصح باستخدام بريد إلكتروني شائع الاستخدام، حيث سيتم إرسال التحقق والإشعارات إليه)، وقم بتعيين كلمة مرور (يجب أن تتضمن أحرفًا وأرقامًا وأحرفًا خاصة).</li><li>أكد التحقق البشري، واتبع <strong>التعليمات</strong> للتحقق من بريدك الإلكتروني، وسيتم إنشاء حسابك.</li></ol><h2 id="إنشاء-مستودعك-الأول-على-github" tabindex="-1">إنشاء مستودعك الأول على GitHub <a class="header-anchor" href="#إنشاء-مستودعك-الأول-على-github" aria-label="Permalink to “إنشاء مستودعك الأول على GitHub”">​</a></h2><p>بعد ذلك، سننشئ أول مجلد تخزين، والذي يُعرف أيضًا بالمستودع أو &quot;repo&quot;.</p><p><img src="'+d+'" alt=""><img src="'+g+'" alt=""></p><p><img src="'+c+'" alt=""></p><ol><li>Repository name: اسم المستودع كما سيظهر للآخرين.</li><li>Description: وصف تفصيلي للمستودع.</li><li>Choose visibility: للمستودعات الشخصية، إذا تم تعيينها كـ private، فلن يتمكن إلا أنت والأشخاص المدعوون خصيصًا من رؤيتها. إذا تم تعيينها كـ public، فسيتمكن الجميع من رؤيتها. بالنسبة للمستودعات داخل المنظمة، إذا كانت Private، فلن يتمكن إلا أعضاء المنظمة من رؤيتها. إذا كانت Public، يمكن للأشخاص خارج المنظمة رؤيتها أيضًا.</li><li>README: العرف السائد هو أن يكون لكل مستودع ملف README. يمكنك اعتباره مقدمة شاملة للمستودع، تتضمن تعليمات الاستخدام وقائمة الملفات وطرق التشغيل.</li><li>Add .gitignore and license: <ol><li>يخبر ملف .gitignore نظام Git بتجاهل مجلدات أو ملفات معينة عند الرفع إلى GitHub، وبالتالي لن يتم تتبعها أو إضافتها إلى منطقة الإعداد. هذا مفيد لملفات الاختبار المؤقتة أو حزم التبعية أو الملفات الكبيرة. بمجرد التحديد، لن يتم تتبع هذه الملفات بعد الآن.</li><li>يشير license إلى نوع ترخيص المصدر المفتوح الذي تختاره. تُفصل التراخيص المختلفة ما إذا كان يمكن للآخرين استخدام كودك لأغراض تجارية، وتتضمن شروطًا وأحكامًا أخرى.</li></ol></li></ol><p>يُنصح بتحديد &quot;Add README&quot;، وتعيين رؤية المستودع إلى &quot;Private&quot;، وملء اسم المستودع والوصف حسب تفضيلاتك، ثم النقر على &quot;Create repository&quot; لإكمال إنشاء أول مستودع بعيد.</p><p><img src="'+b+'" alt=""></p><p>بعد ذلك، ستمتلك مستودعًا نظيفًا بدون أي ملفات إضافية. يمكنك الآن البدء برفع الملفات.</p><p><img src="'+k+'" alt=""></p><p>أمر الحصول على المستودع هو <code>git clone</code>، لكنه يحتاج إلى عنوان المستودع. يمكنك العثور على عنوان المستودع بالنقر على زر &quot;Code&quot; الأخضر، حيث سترى خيارات HTTPS و SSH. عادةً، يمكنك استخدام أي من الطريقتين لتنزيل المستودع على جهازك المحلي (فقط بهذه الطريقة يمكنك تعديل الملفات ورفعها).</p><p><img src="'+m+'" alt=""></p><p>بشكل عام، استنساخ المستودعات عبر HTTP مناسب للتنزيل المؤقت واختبار مستودعات الآخرين، لكن لا يُنصح به للتطوير الشخصي. للحصول على تجربة تعلم أفضل، يجب عليك إعداد مصادقة SSH أولاً.</p><h2 id="ربط-ssh-المحلي" tabindex="-1">ربط SSH المحلي <a class="header-anchor" href="#ربط-ssh-المحلي" aria-label="Permalink to “ربط SSH المحلي”">​</a></h2><p>في GitHub، يعني &quot;ربط بروتوكول SSH&quot; أساسًا ربط مفتاح SSH العام لجهازك المحلي بحساب GitHub الخاص بك، مما يسمح لـ GitHub بالتعرف على جهازك عبر بروتوكول SSH. هذا يتيح لك تشغيل المستودعات البعيدة بأمان دون الحاجة إلى كلمة مرور (مثل استنساخ أو دفع أو سحب الكود).</p><p>ببساطة: الأمر يشبه إعطاء جهازك &quot;بطاقة دخول خاصة بـ GitHub&quot;. بعد الربط، عندما يصل جهازك إلى مستودعات GitHub عبر بروتوكول SSH، سيتحقق GitHub من &quot;بطاقة الدخول&quot; هذه (مفتاح SSH العام الخاص بك). بمجرد التأكد من أنه جهازك المصرح لك، يمكنك العمل مباشرة — دون الحاجة لإدخال اسم المستخدم وكلمة المرور في كل مرة.</p><blockquote><p>💡 ما هو SSH</p></blockquote><h3 id="لماذا-نحتاج-إلى-ربط-بروتوكول-ssh؟" tabindex="-1">لماذا نحتاج إلى ربط بروتوكول SSH؟ <a class="header-anchor" href="#لماذا-نحتاج-إلى-ربط-بروتوكول-ssh؟" aria-label="Permalink to “لماذا نحتاج إلى ربط بروتوكول SSH؟”">​</a></h3><p>يدعم GitHub بروتوكولين رئيسيين لتشغيل المستودعات: بروتوكول HTTPS وبروتوكول SSH:</p><ul><li>بروتوكول HTTPS: كل عملية (مثل push) تتطلب إدخال اسم المستخدم وكلمة المرور لـ GitHub (أو رمز الوصول الشخصي PAT). عملية التحقق مرهقة وتحمل خطر تسريب كلمة المرور.</li><li>بروتوكول SSH: تتم المصادقة عبر &quot;زوج مفاتيح&quot;، لذلك لا حاجة لإدخال كلمة المرور بشكل متكرر، والنقل المشفر أكثر أمانًا.</li></ul><p>&quot;ربط بروتوكول SSH&quot; هو <strong>خطوة</strong> أساسية لتفعيل مصادقة GitHub عبر SSH — فقط بعد &quot;ربط&quot; مفتاح SSH العام المحلي بحساب GitHub، يمكن لـ GitHub التعرف على جهازك والسماح بعمليات SSH على المستودع.</p><h3 id="المنطق-الأساسي-لـ-الربط-دور-زوج-مفاتيح-ssh" tabindex="-1">المنطق الأساسي لـ &quot;الربط&quot;: دور زوج مفاتيح SSH <a class="header-anchor" href="#المنطق-الأساسي-لـ-الربط-دور-زوج-مفاتيح-ssh" aria-label="Permalink to “المنطق الأساسي لـ &quot;الربط&quot;: دور زوج مفاتيح SSH”">​</a></h3><p>تعتمد مصادقة SSH على زوج مفاتيح (مفتاح عام + مفتاح خاص)، وهما ملفات تشفير متطابقة. بعد التوليد، تحتاج إلى تقديم &quot;المفتاح العام&quot; لـ GitHub (&quot;الربط&quot;)، بينما يبقى &quot;المفتاح الخاص&quot; على جهازك المحلي:</p><ol><li>المفتاح الخاص: يُخزن على جهازك المحلي (مثل الحاسوب) في دليل محدد (عادةً <code>~/.ssh/</code>)، ويعمل كـ&quot;مفتاحك الحصري&quot;، ويجب عدم مشاركته مع أي شخص نهائيًا.</li><li>المفتاح العام: هذا &quot;قفل&quot; يمكن مشاركته علنًا — تحتاج إلى نسخه إلى قائمة &quot;SSH keys&quot; في حساب GitHub (عملية &quot;الربط&quot;).</li></ol><p>عندما تشغل مستودع GitHub عبر SSH (مثلاً <code>git push git@github.com:xxx/xxx.git</code>):</p><ul><li>يستخدم جهازك المحلي المفتاح الخاص لتشفير &quot;طلب العملية&quot; وإرساله إلى GitHub؛</li><li>بعد استلام الطلب، يحاول GitHub فك التشفير باستخدام المفتاح العام الذي ربطته سابقًا؛</li><li>إذا نجح فك التشفير، يتم تأكيد أن جهازك مصرح لك، وتُسمح العملية؛ وإلا، يُرفض الوصول.</li></ul><h3 id="خطوات-الربط-العملية-العملية-الأساسية" tabindex="-1"><strong>خطوات</strong> &quot;الربط&quot; العملية (العملية الأساسية) <a class="header-anchor" href="#خطوات-الربط-العملية-العملية-الأساسية" aria-label="Permalink to “خطوات &quot;الربط&quot; العملية (العملية الأساسية)”">​</a></h3><p>بمجرد فهمك للمبدأ، تصبح العملية الفعلية بسيطة — الجوهر هو &quot;توليد زوج مفاتيح ← رفع المفتاح العام إلى GitHub&quot;:</p><ol><li><p>توليد زوج مفاتيح SSH محليًا</p><ol><li>استخدام Trae للحصول على المفتاح العام (مُوصى بها) <strong>نصيحة</strong>: <code>Help me create the SSH key needed for GitHub login. My email is your_email@gmail.com , Please return the public key for me to copy</code></li></ol><p><img src="'+G+'" alt=""></p><p>بعد إدخال <strong>النصيحة</strong>، تحتاج أيضًا إلى الضغط على Enter في الطرفية على اليسار، وإلا سينتظر الأمر دون تنفيذ. بما أن Trae لا يمكنه تنفيذ أي أحكام شرطية، نحتاج فقط للضغط المستمر على Enter.</p><p>أخيرًا، سترى Trae على اليمين قد أعاد المفتاح العام الذي قرأه. فقط انسخه واستعد للصقه في <strong>الخطوة التالية</strong>.</p><p><img src="'+H+'" alt=""> 2. الحصول على المفتاح العام يدويًا افتح طرفيتك المحلية (على Windows استخدم Git Bash أو PowerShell؛ على macOS/Linux استخدم الطرفية)، وأدخل الأمر التالي (استبدل <code>your_email@example.com</code> بالبريد الإلكتروني المستخدم عند تسجيل حساب GitHub):</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your_email@example.com&quot;</span></span></code></pre></div><ol><li>اضغط Enter لقبول القيم الافتراضية (مسار الملف الافتراضي، بدون كلمة مرور، أو قم بتعيين كلمة مرور حسب الحاجة). سيؤدي هذا إلى توليد ملفين في دليل <code>~/.ssh/</code>: <ul><li><code>id_ed25519</code>: المفتاح الخاص (محفوظ محليًا، <strong>لا تشاركه أبدًا</strong>)؛</li><li><code>id_ed25519.pub</code>: المفتاح العام (يجب رفعه إلى GitHub).</li></ul></li></ol></li><li><p>&quot;ربط&quot; المفتاح العام بحساب GitHub</p></li></ol><p>هذه هي <strong>خطوة</strong> الربط الأساسية — إضافة المفتاح العام المحلي إلى قائمة &quot;SSH keys&quot; في حساب GitHub:</p><ol><li>نسخ محتوى المفتاح العام: <ol><li>Trae:</li><li>Windows: افتح <code>C:\\Users\\&lt;your&gt;\\.ssh\\id_ed25519.pub</code> بالمفكرة وانسخ كل محتواه؛</li><li>macOS/Linux: شغّل <code>cat ~/.ssh/id_ed25519.pub</code> في الطرفية وانسخ كل المخرجات (من بداية <code>ssh-ed25519</code> إلى البريد الإلكتروني في النهاية).</li></ol></li><li>سجل الدخول إلى GitHub وانتقل إلى صفحة &quot;إدارة SSH Key&quot;: <ol><li>انقر على الصورة الرمزية في الزاوية العلوية اليمنى ← Settings ← القائمة الجانبية SSH and GPG keys ← انقر على New SSH key. <img src="'+S+'" alt=""><img src="'+q+'" alt=""></li><li>أدخل أي عنوان (مثل &quot;your local computer&#39;s SSH&quot;)، ثم الصق مفتاح SSH العام الذي حصلت عليه للتو هنا.</li></ol></li></ol><p><img src="'+y+'" alt=""></p><p><img src="'+F+'" alt=""></p><ol start="3"><li>التحقق من نجاح الربط</li></ol><p>أدخل الأمر التالي في الطرفية (<strong>يمكن لـ Trae أيضًا تنفيذ العمليات التالية</strong>) لاختبار ما إذا كان GitHub يمكنه التعرف على جهازك:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com</span></span></code></pre></div><ul><li>إذا رأيت رسالة مثل <code>Hi [your GitHub username]! You&#39;ve successfully authenticated...</code>، فهذا يعني أنك ربطت المفتاح بنجاح؛</li><li>إذا واجهت أخطاء، فعادةً يكون السبب نسخ المفتاح العام بشكل غير كامل، أو صلاحيات المفتاح الخاص مرتفعة للغاية (دليل <code>~/.ssh/</code> المحلي يجب أن يكون قابلًا للقراءة والكتابة من قبلك فقط). تحقق من هذه المشكلات حسب الحاجة.</li></ul><h3 id="ملاحظات-مهمة" tabindex="-1"><strong>ملاحظات مهمة</strong> <a class="header-anchor" href="#ملاحظات-مهمة" aria-label="Permalink to “ملاحظات مهمة”">​</a></h3><p>إذا كان لديك أجهزة متعددة (مثل حاسوب محمول وحاسوب مكتبي)، تحتاج إلى توليد زوج مفاتيح SSH منفصل لكل جهاز، وربط كل مفتاح عام بنفس حساب GitHub — كل جهاز يملك &quot;بطاقة دخول&quot; خاصة به.</p><p>لا تشارك أبدًا مفتاحك الخاص (لا ترفعه إلى GitHub أو تشاركه مع الآخرين)، وإلا قد ينتحل شخصيتك لتشغيل مستودعاتك. إذا تم تسريب المفتاح الخاص، احذف المفتاح العام المقابل من GitHub فورًا وقم بتوليد زوج مفاتيح جديد.</p><p>بعد ربط SSH، استخدم عنوان المستودع بتنسيق SSH (مثل <code>git@github.com:username/repository.git</code>) للعمليات، بدلاً من تنسيق HTTPS (مثل <code>https://github.com/username/repository.git</code>). إذا كنت قد استنسخت المستودع سابقًا عبر HTTPS، يمكنك تبديل البروتوكول باستخدام <code>git remote set-url origin &lt;new&gt;</code>.</p><h1 id="استخدام-trae-لعمليات-github" tabindex="-1">استخدام Trae لعمليات GitHub <a class="header-anchor" href="#استخدام-trae-لعمليات-github" aria-label="Permalink to “استخدام Trae لعمليات GitHub”">​</a></h1><p>لقد شرحنا ما هو Git، وما هو GitHub، وما هو SSH، وكيفية إعداده. الآن يمكنك استخدام Trae بحرية لتنفيذ عمليات Git. أولًا، لنتعلم كيفية استنساخ مستودع بعيد إلى جهازك المحلي.</p><h2 id="git-clone-تنزيل-مستودع-موجود" tabindex="-1">Git clone: تنزيل مستودع موجود <a class="header-anchor" href="#git-clone-تنزيل-مستودع-موجود" aria-label="Permalink to “Git clone: تنزيل مستودع موجود”">​</a></h2><p>يمكنك ببساطة إخباره بعنوان المستودع الذي تريد استنساخه</p><p><img src="'+f+'" alt=""></p><h2 id="git-pull-الحصول-على-التحديثات-من-المستودع-البعيد" tabindex="-1">Git pull: الحصول على التحديثات من المستودع البعيد <a class="header-anchor" href="#git-pull-الحصول-على-التحديثات-من-المستودع-البعيد" aria-label="Permalink to “Git pull: الحصول على التحديثات من المستودع البعيد”">​</a></h2><p>قبل تحديث المستودع في كل مرة، وبما أنه قد يكون مشتركًا بين عدة أشخاص، تحتاج أولاً إلى سحب أحدث التغييرات. بعد ذلك، يمكنك تعديل الملفات ودفعها.</p><p><strong>تأكد من تضمين اسم المجلد ومساره النسبي أو المطلق، لتجنب الدفع إلى مستودع خاطئ.</strong></p><p>prompt:<code>Help me pull this repository AIID-TEST in ./AIID-TEST.</code></p><h2 id="git-commit-git-push-تحضير-التحديثات-ودفعها-إلى-github" tabindex="-1">Git commit &amp; Git push: تحضير التحديثات ودفعها إلى GitHub <a class="header-anchor" href="#git-commit-git-push-تحضير-التحديثات-ودفعها-إلى-github" aria-label="Permalink to “Git commit &amp; Git push: تحضير التحديثات ودفعها إلى GitHub”">​</a></h2><p>عندما يكون كل شيء جاهزًا، يمكنك محاولة تعديل الملفات المحلية، أو إضافة أو حذف عناصر في المجلد. ثم اطلب من Trae اكتشاف التغييرات ومساعدتك في دفعها إلى GitHub.</p><p>prompt:<code>I finished. Commit and push to the repository AIID-TEST in ./AIID-TEST.</code></p><p><img src="'+_+'" alt=""></p><p>تم الدفع بنجاح. يمكنك الآن رؤية المحتوى المُحدَّث على GitHub.</p><h1 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h1><ul><li>Pro Git book <a href="https://git-scm.com/book/en/v2" target="_blank" rel="noreferrer">https://git-scm.com/book/en/v2</a></li><li>GitHub Docs <a href="https://docs.github.com/en" target="_blank" rel="noreferrer">https://docs.github.com/en</a></li></ul>',92)])])}const D=t(C,[["render",x]]);export{A as __pageData,D as default};
